213	// Decode the --key-hex argument, emitting the shared key-format diagnostic
214	// (which never echoes the submitted key) on failure.
215	bool parseKey(const CommandSpec& spec, const std::string& keyHex,
216	              std::vector<unsigned char>& key) {
217	    if (decodeHex(keyHex, key)) {
218	        return true;
219	    }
220	    std::cerr << "messagetag " << spec.name
221	              << ": error: invalid --key-hex: expected a non-empty, "
222	                 "even-length string of hexadecimal characters (0-9, a-f, A-F); "
223	                 "every two characters denote one key byte and leading zeros must "
224	                 "be kept; a 0x prefix and whitespace are not accepted\n"
225	              << spec.usage;
226	    return false;
227	}
228	
229	// The outcome of authenticating one message: the tag was produced, the
230	// message source failed, or the HMAC computation itself failed.
231	enum class HmacStatus { kSuccess, kReadError, kCryptoError };
232	
233	// A streaming HMAC-SHA-256 computation: Init with the key at construction,
234	// feed message bytes chunk by chunk with update(), produce the tag once
235	// with finish(). All message sources feed their bytes through this one
236	// path, so the same key and the same bytes always yield the same tag no
237	// matter which source they came from, and no matter how the input was
238	// split into reads.
239	//
240	// HMAC_Init_ex performs the standard RFC 2104 key normalization itself, so
241	// keys longer than the SHA-256 block size are hashed exactly as the
242	// standard requires; the resulting tag is identical to the one-shot HMAC()
243	// interface on both OpenSSL 1.1.1 and OpenSSL 3.x. The key is validated to
244	// be non-empty before this is constructed, so key.data() is always valid.
245	class HmacSha256Stream {
246	  public:
247	    explicit HmacSha256Stream(const std::vector<unsigned char>& key)
248	        : ctx_(HMAC_CTX_new(), &HMAC_CTX_free) {
249	        usable_ = ctx_ != nullptr &&
250	                  HMAC_Init_ex(ctx_.get(), key.data(),
251	                               static_cast<int>(key.size()), EVP_sha256(),
252	                               nullptr) == 1;
253	    }
254	
255	    bool usable() const { return usable_; }
256	
257	    bool update(const char* data, std::size_t length) {
258	        return HMAC_Update(ctx_.get(),
259	                           reinterpret_cast<const unsigned char*>(data),
260	                           length) == 1;
261	    }
262	
263	    bool finish(std::array<unsigned char, EVP_MAX_MD_SIZE>& mac,
264	                std::size_t& macLength) {
265	        unsigned int outLength = 0;
266	        if (HMAC_Final(ctx_.get(), mac.data(), &outLength) != 1) {
267	            return false;
268	        }
269	        macLength = outLength;
270	        return true;
271	    }
272	
273	  private:
274	    std::unique_ptr<HMAC_CTX, decltype(&HMAC_CTX_free)> ctx_;
275	    bool usable_ = false;
276	};
277	
278	// A message source delivers the message one chunk at a time through
279	// readChunk(): fill `buffer` with up to `capacity` bytes and return how
280	// many were delivered, return 0 once the message has ended normally, or
281	// return -1 when the source fails (after which no further bytes are
282	// requested). How a chunk is obtained -- and what counts as a failure --
283	// is each source's own business; the shared authentication below only
284	// ever sees the resulting byte stream.
285	
286	// A file source delivers the file's raw bytes exactly as stored: they
287	// are not interpreted as text, trailing newlines are kept, line endings
288	// are not converted and zero bytes are preserved. An empty file ends
289	// immediately, which authenticates the empty message. Failing to open
290	// the file is a read failure reported on the first chunk.
291	class FileMessageSource {
292	  public:
293	    explicit FileMessageSource(const std::string& path)
294	        : in_(path, std::ios::binary | std::ios::in), failed_(!in_) {}
295	
296	    ssize_t readChunk(char* buffer, std::size_t capacity) {
297	        if (failed_) {
298	            return -1;
299	        }
300	        if (ended_) {
301	            return 0;
302	        }
303	        in_.read(buffer, static_cast<std::streamsize>(capacity));
304	        // badbit means the read itself failed -- possibly after a
305	        // non-empty prefix was already delivered. A short read at EOF
306	        // is normal, and those remaining bytes still participate; the
307	        // zero-byte read past the end is the normal end of the message.
308	        if (in_.bad()) {
309	            failed_ = true;
310	            return -1;
311	        }
312	        if (in_.eof()) {
313	            ended_ = true;
314	        }
315	        return static_cast<ssize_t>(in_.gcount());
316	    }
317	
318	  private:
319	    std::ifstream in_;
320	    bool failed_ = false;
321	    bool ended_ = false;
322	};
323	
324	// A standard-input source (selected by "--file -") delivers every byte
325	// that arrives on file descriptor 0 until the input ends normally (EOF).
326	// Bytes arriving in several installments are simply several chunks,
327	// which does not change the message. A read interrupted by EINTR before
328	// any byte arrived is retried in place: the bytes received so far still
329	// belong to the same message. Any other read failure ends the source
330	// with an error.
331	class StdinMessageSource {
332	  public:
333	    ssize_t readChunk(char* buffer, std::size_t capacity) {
334	        for (;;) {
335	            ssize_t n = ::read(STDIN_FILENO, buffer, capacity);
336	            if (n >= 0) {
337	                return n;  // n == 0 is the clean end of input
338	            }
339	            if (errno != EINTR) {
340	                return -1;
341	            }
342	        }
343	    }
344	};
345	
346	// The single place that maintains how a message is authenticated: start
347	// HMAC-SHA-256 with the key, feed every chunk the source delivers in the
348	// order it arrives, and finish exactly once, when the source reports the
349	// message has ended normally. Both sources feed their bytes through this
350	// one path, so the same key and the same bytes always yield the same tag
351	// no matter which source they came from, no matter how the input was
352	// split into reads, and no matter whether the last read filled the
353	// buffer.
354	//
355	// The message is never stored whole: regardless of its length, only one
356	// 64 KiB read buffer is needed on top of the constant-size HMAC context.
357	// A read failure -- including one after a non-empty prefix has already
358	// been fed to HMAC -- aborts authentication: finish() is never reached,
359	// so the received prefix can never be finalized as if it were the whole
360	// message.
361	template <typename Source>
362	HmacStatus authenticateMessage(const std::vector<unsigned char>& key,
363	                               Source& source,
364	                               std::array<unsigned char, EVP_MAX_MD_SIZE>& mac,
365	                               std::size_t& macLength) {
366	    HmacSha256Stream hmac(key);
367	    if (!hmac.usable()) {
368	        return HmacStatus::kCryptoError;
369	    }
370	
371	    std::array<char, 65536> buffer{};
372	    for (;;) {
373	        ssize_t n = source.readChunk(buffer.data(), buffer.size());
374	        if (n > 0) {
375	            if (!hmac.update(buffer.data(), static_cast<std::size_t>(n))) {
376	                return HmacStatus::kCryptoError;
377	            }
378	            continue;
379	        }
380	        if (n == 0) {
381	            break;  // clean end of the message: every byte has been fed
382	        }
383	        return HmacStatus::kReadError;
384	    }
385	
386	    if (!hmac.finish(mac, macLength)) {
387	        return HmacStatus::kCryptoError;
388	    }
389	    return HmacStatus::kSuccess;
390	}
391	
392	// Output of the shared preparation stage that the command-specific
393	// decision still needs afterwards.
394	struct PreparedAuthentication {
395	    // verify only: the supplied --tag-hex decoded to 32 bytes; unused by
396	    // tag, which has no tag to compare against.
397	    std::vector<unsigned char> expectedTag;
398	};
399	
400	// Prepare and perform the message authentication that both commands share.
401	// This is the single place that maintains the ordered checks leading up to
402	// the command-specific result:
403	//
404	//   1. parse exactly this command's value-taking options (unknown argument
405	//      or missing value -> exit 2 with that command's usage);
406	//   2. require --key-hex/--file, and additionally --tag-hex when
407	//      `expectTag` is set (exit 2);
408	//   3. decode the key, and the supplied tag for verify, BEFORE the message
409	//      source is touched, so a malformed key/tag is a parameter error
410	//      (exit 2) even when the file does not exist -- and, with "--file -",
411	//      without waiting for standard input to arrive or end;
412	//   4. stream the whole message through HMAC-SHA-256, from the named file
413	//      or -- when --file is exactly "-" -- from standard input until its
414	//      normal end (read or computation failure -> exit 1, with no result
415	//      produced; a prefix read before a failure is never finalized as the
416	//      message).
417	//
418	// Every diagnostic goes out from here under the failing command's own name
419	// and usage, so one and the same failure behaviour no longer has to be kept
420	// in sync between runTag and runVerify. Returns the process exit code; on
421	// success it is 0 and `mac`/`macLength` (plus `prepared` for verify) hold
422	// what the caller needs for its own result handling; otherwise the caller
423	// returns the non-zero code unchanged.
424	int prepareAuthentication(const CommandSpec& spec, int argc, char* argv[],
425	                          bool expectTag,
426	                          std::array<unsigned char, EVP_MAX_MD_SIZE>& mac,
427	                          std::size_t& macLength,
428	                          PreparedAuthentication& prepared) {
429	    std::map<std::string, std::string> opts;
430	    if (!parseValueOptions(spec, argc, argv, opts)) {
431	        return 2;
432	    }
433	    if (!requireOption(spec, opts, "--key-hex") ||
434	        !requireOption(spec, opts, "--file") ||
435	        (expectTag && !requireOption(spec, opts, "--tag-hex"))) {
436	        return 2;
437	    }
438	    const std::string& keyHex = opts["--key-hex"];
439	    const std::string& filePath = opts["--file"];
440	
441	    // All input-format checks happen before the message source is touched,
442	    // so a malformed key or tag is reported as a parameter error (exit 2)
443	    // even when the message file does not exist -- and, with "--file -",
444	    // without ever waiting for standard input.
445	    std::vector<unsigned char> key;
446	    if (!parseKey(spec, keyHex, key)) {
447	        return 2;
448	    }
449	
450	    if (expectTag) {
451	        // The supplied tag must decode to exactly 32 bytes (64 hex
452	        // characters); decodeHex already rejects empty input, odd length,
453	        // non-hex characters and whitespace, which also rules out a 0x
454	        // prefix. The submitted tag is deliberately not echoed back.
455	        if (!decodeHex(opts["--tag-hex"], prepared.expectedTag) ||
456	            prepared.expectedTag.size() != kTagBytes) {
457	            std::cerr << "messagetag " << spec.name
458	                      << ": error: invalid --tag-hex: expected exactly 64 "
459	                         "hexadecimal characters denoting 32 bytes (0-9, a-f, "
460	                         "A-F); empty, truncated or over-long values, embedded "
461	                         "whitespace and a 0x prefix are not accepted\n"
462	                      << spec.usage;
463	            return 2;
464	        }
465	    }
466	
467	    // A --file value of exactly "-" reads the message from standard input
468	    // until its normal end; a file literally named "-" stays reachable as
469	    // "./-" or by full path, and every other value is a file path read the
470	    // usual way. Either way the bytes go through the one shared
471	    // authenticateMessage() above; only the source differs.
472	    const bool fromStdin = filePath == "-";
473	    HmacStatus status;
474	    if (fromStdin) {
475	        StdinMessageSource source;
476	        status = authenticateMessage(key, source, mac, macLength);
477	    } else {
478	        FileMessageSource source(filePath);
479	        status = authenticateMessage(key, source, mac, macLength);
480	    }
481	    switch (status) {
482	        case HmacStatus::kReadError:
483	            // The partially read prefix must never be authenticated as if
484	            // it were the whole message. Neither diagnostic echoes the key,
485	            // the supplied tag or a recomputed tag.
486	            if (fromStdin) {
487	                std::cerr << "messagetag " << spec.name
488	                          << ": error: failed to read standard input\n";
489	            } else {
490	                std::cerr << "messagetag " << spec.name
491	                          << ": error: failed to read file: " << filePath
492	                          << "\n";
493	            }
494	            return 1;
495	        case HmacStatus::kCryptoError:
496	            std::cerr << "messagetag " << spec.name
497	                      << ": error: HMAC-SHA-256 computation failed\n";
498	            return 1;
499	        case HmacStatus::kSuccess:
500	            return 0;
501	    }
502	    return 1;  // unreachable: every status is handled above
503	}
504	
505	int runTag(int argc, char* argv[]) {
506	    std::array<unsigned char, EVP_MAX_MD_SIZE> mac{};
507	    std::size_t macLength = 0;
508	    PreparedAuthentication prepared;
509	    int rc = prepareAuthentication(tagSpec(), argc, argv, /*expectTag=*/false,
510	                                   mac, macLength, prepared);
511	    if (rc != 0) {
512	        return rc;
513	    }
514	
515	    std::string tagLine = hexEncode(mac.data(), macLength);
516	    tagLine.push_back('\n');
517	    // Exit 0 only once the whole line is confirmed written; a correct tag
518	    // does not make a failed/partial result output a success.
519	    if (!emitResultLine("tag", tagLine)) {
520	        return 1;
521	    }
522	    return 0;
523	}
524	
525	// Compare two fixed-length byte strings without leaking the length of any
526	// matching prefix: the loop always touches every byte and accumulates all
527	// differences, so the running time does not depend on where (or whether)
528	// the inputs differ.
529	bool constantTimeEqual(const unsigned char* a, const unsigned char* b,
530	                       std::size_t length) {
531	    unsigned char diff = 0;
532	    for (std::size_t i = 0; i < length; ++i) {
533	        diff |= static_cast<unsigned char>(a[i] ^ b[i]);
534	    }
535	    return diff == 0;
536	}
537	
538	int runVerify(int argc, char* argv[]) {
539	    std::array<unsigned char, EVP_MAX_MD_SIZE> mac{};
540	    std::size_t macLength = 0;
541	    PreparedAuthentication prepared;
542	    int rc = prepareAuthentication(verifySpec(), argc, argv,
543	                                   /*expectTag=*/true, mac, macLength,
544	                                   prepared);
545	    if (rc != 0) {
546	        return rc;
547	    }
548	
549	    if (macLength != kTagBytes ||
550	        !constantTimeEqual(mac.data(), prepared.expectedTag.data(),
551	                           kTagBytes)) {
552	        // State only that authentication failed; do not assign a cause (the
553	        // message, the key or the tag could each be the one that differs),
554	        // and never print the recomputed tag, a matched prefix or the key.
555	        std::cerr << "messagetag verify: error: authentication tag mismatch: "
556	                     "the supplied tag does not match the given key and file "
557	                     "content\n";
558	        return 3;
559	    }
560	
561	    // Exit 0 only once the whole "OK\n" line is confirmed written; a
562	    // passed comparison does not make a failed/partial result output a
563	    // success.
564	    if (!emitResultLine("verify", "OK\n")) {
565	        return 1;
566	    }
567	    return 0;
568	}
569	
570	}  // namespace
571	
572	int main(int argc, char* argv[]) {
573	    if (argc == 2 && std::string_view(argv[1]) == "--version") {
574	        std::cout << "messagetag 0.1.0\n";
575	        return 0;
576	    }
