578	                      std::string_view(argv[1]) == "verify")) {
579	        // A closed downstream pipe must surface as an EPIPE write failure
580	        // (reported and mapped to exit 1), not as the default SIGPIPE kill,
581	        // which would leave the shell with a signal-terminated status and
582	        // no diagnostic. Ignore SIGPIPE so write(2) returns EPIPE instead.
583	        std::signal(SIGPIPE, SIG_IGN);
